export const parseLabelIDsInEvent = <T extends Element>(element: T, changes: T & LabelIDsChanges): T => {
    const omitted = omit(changes, ['LabelIDsRemoved', 'LabelIDsAdded']);
    if (isMessage(element)) {
        if (omitted?.LabelIDs) {
            return { ...element, ...omitted };
